-- Rebuild Medina Book 3 lesson 12 strictly from the supplied Arabic sharh.
-- Canonical page references: Sharkh_Medinskiy_3.pdf, PDF pages 48-52.
-- Five Qur'anic strings hidden by DOC control characters were transcribed literally from visible PDF pages 49 and 51.

begin;
do $migration$
declare old_rule_count integer; new_rule_count integer; source_count integer;
begin
  select count(*) into old_rule_count from public.rules where course_name = 'Мединский курс (Том 3)' and lesson_number = '12';
  if old_rule_count <> 3 then raise exception 'Expected 3 generated Book 3 lesson 12 rules, found %', old_rule_count; end if;

  delete from public.rule_sections where rule_id in (select id from public.rules where course_name = 'Мединский курс (Том 3)' and lesson_number = '12');
  delete from public.rule_sources where rule_id in (select id from public.rules where course_name = 'Мединский курс (Том 3)' and lesson_number = '12');
  delete from public.rules where course_name = 'Мединский курс (Том 3)' and lesson_number = '12';

  insert into public.rules (course_name, lesson_number, title, content, sort_order, rule_kind, summary, rule_ar)
  values
    ('Мединский курс (Том 3)', '12', 'الْمَفْعُولُ فِيهِ (обстоятельство времени или места)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar" dir="rtl" lang="ar"><span class="ar-tone-nasb">الْمَفْعُولُ فِيهِ</span> ٱسْمٌ مَنْصُوبٌ بِتَقْدِيرِ <span class="ar-tone-particle">فِي</span>، يُذْكَرُ لِبَيَانِ زَمَنِ وُقُوعِ الْفِعْلِ أَوْ مَكَانِهِ، وَيُسَمَّى <span class="ar-tone-nasb">ظَرْفًا</span>.</span><p class="rule-study-text">Это имя в винительном падеже, при котором подразумевается предлог «в»; оно указывает время или место совершения действия и называется обстоятельством.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Два вида обстоятельства</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">نَوْعُ الظَّرْفِ</span><span class="rule-table-ru">вид обстоятельства</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَا يَدُلُّ عَلَيْهِ</span><span class="rule-table-ru">что обозначает</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">ظَرْفُ زَمَانٍ</span><span class="rule-table-ru">обстоятельство времени</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">زَمَنُ وُقُوعِ الْفِعْلِ</span><span class="rule-table-ru">время совершения действия</span></td></tr><tr><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">ظَرْفُ مَكَانٍ</span><span class="rule-table-ru">обстоятельство места</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">مَكَانُ وُقُوعِ الْفِعْلِ</span><span class="rule-table-ru">место совершения действия</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Все примеры обстоятельства времени</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">التَّرْجَمَةُ</span><span class="rule-table-ru">перевод</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">تَقْدِيرُ فِي</span><span class="rule-table-ru">подразумеваемое «в»</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">سَافَرْتُ لَيْلًا.</span><span class="rule-table-ru">Я путешествовал ночью.</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">سَافَرْتُ فِي اللَّيْلِ.</span><span class="rule-table-ru">Я путешествовал в ночное время.</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">فِي اللَّيْلِ</span><span class="rule-table-ru">в ночное время</span></td></tr><tr><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">خَرَجْتُ مَسَاءً.</span><span class="rule-table-ru">Я вышел вечером.</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">خَرَجْتُ فِي الْمَسَاءِ.</span><span class="rule-table-ru">Я вышел в вечернее время.</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">فِي الْمَسَاءِ</span><span class="rule-table-ru">вечером</span></td></tr><tr><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">جِئْتُ قَبْلَ سَاعَةٍ.</span><span class="rule-table-ru">Я пришёл час назад.</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">قَبْلَ</span><span class="rule-table-ru">до; тому назад</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">فِي زَمَنٍ قَبْلَ سَاعَةٍ</span><span class="rule-table-ru">во время, предшествовавшее этому на час</span></td></tr><tr><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">سَأُسَافِرُ صَبَاحًا أَوْ غَدًا إِنْ شَاءَ اللَّهُ.</span><span class="rule-table-ru">Я отправлюсь утром или завтра, если пожелает Аллах.</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">صَبَاحًا، غَدًا</span><span class="rule-table-ru">утром; завтра</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">فِي الصَّبَاحِ، فِي يَوْمِ غَدٍ</span><span class="rule-table-ru">утром; в завтрашний день</span></td></tr><tr><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">نِمْتُ بَعْدَ نَوْمِكَ.</span><span class="rule-table-ru">Я уснул после того, как ты уснул.</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">بَعْدَ</span><span class="rule-table-ru">после</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">فِي زَمَنٍ بَعْدَ نَوْمِكَ</span><span class="rule-table-ru">во время после твоего сна</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Коранический пример</span><div class="rule-example-card"><span class="rule-example-ar rule-quran-ar ar-tone-nasb" dir="rtl" lang="ar">﴿ وَجَاءُوا أَبَاهُمْ عِشَاءً يَبْكُونَ ﴾</span><span class="rule-example-ru">«И они пришли к своему отцу вечером, плача».</span></div></div><div class="rule-study-card"><span class="rule-card-kicker">Все примеры обстоятельства места</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">التَّرْجَمَةُ</span><span class="rule-table-ru">перевод</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">تَقْدِيرُ فِي</span><span class="rule-table-ru">подразумеваемое «в»</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">جَلَسْتُ هُنَا.</span><span class="rule-table-ru">Я сидел здесь.</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">هُنَا</span><span class="rule-table-ru">здесь</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">فِي هَذَا الْمَكَانِ</span><span class="rule-table-ru">в этом месте</span></td></tr><tr><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">مَشَيْتُ يَمِينَ الطَّرِيقِ.</span><span class="rule-table-ru">Я шёл по правой стороне дороги.</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">يَمِينَ الطَّرِيقِ</span><span class="rule-table-ru">справа от дороги; по её правой стороне</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">فِي يَمِينِ الطَّرِيقِ</span><span class="rule-table-ru">на правой стороне дороги</span></td></tr><tr><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">مَشَيْتُ مِيلًا.</span><span class="rule-table-ru">Я прошёл одну милю.</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">مِيلًا</span><span class="rule-table-ru">милю</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">فِي مَسَافَةِ مِيلٍ</span><span class="rule-table-ru">на расстоянии одной мили</span></td></tr><tr><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">جَلَسْتُ عِنْدَ الْمُدِيرِ.</span><span class="rule-table-ru">Я сидел у директора.</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">عِنْدَ الْمُدِيرِ</span><span class="rule-table-ru">у директора</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">فِي مَكَانٍ عِنْدَ الْمُدِيرِ</span><span class="rule-table-ru">в месте возле директора</span></td></tr><tr><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">نِمْتُ تَحْتَ الشَّجَرَةِ.</span><span class="rule-table-ru">Я спал под деревом.</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">تَحْتَ الشَّجَرَةِ</span><span class="rule-table-ru">под деревом</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">فِي مَكَانٍ تَحْتَ الشَّجَرَةِ</span><span class="rule-table-ru">в месте под деревом</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Коранический пример</span><div class="rule-example-card"><span class="rule-example-ar rule-quran-ar ar-tone-nasb" dir="rtl" lang="ar">﴿ وَبَنَيْنَا فَوْقَكُمْ سَبْعًا شِدَادًا ﴾</span><span class="rule-example-ru">«И воздвигли над вами семь крепких [небес]».</span></div></div><div class="rule-study-card"><span class="rule-card-kicker">Когда слово не разбирается как обстоятельство</span><span class="rule-main-ar ar-tone-nasb" dir="rtl" lang="ar">إِذَا لَمْ تُقَدَّرْ <span class="ar-tone-particle">فِي</span> لَا يُعْرَبُ الِاسْمُ ظَرْفًا، وَكَذَلِكَ إِذَا ذُكِرَتْ <span class="ar-tone-particle">فِي</span>.</span><p class="rule-study-text">Если предлог «в» нельзя подразумевать либо если он уже произнесён, имя не получает разбор обстоятельства.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Сравнение разбора</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример и перевод</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْكَلِمَةُ</span><span class="rule-table-ru">слово</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">إِعْرَابُهَا</span><span class="rule-table-ru">разбор</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">هَذَا يَوْمُ الْعِيدِ.</span><span class="rule-table-ru">Это день праздника.</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">يَوْمُ</span><span class="rule-table-ru">день</span></td><td><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">خَبَرٌ مَرْفُوعٌ</span><span class="rule-table-ru">хабар в именительном падеже</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">سَافَرْتُ فِي اللَّيْلِ.</span><span class="rule-table-ru">Я путешествовал ночью.</span></td><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">اللَّيْلِ</span><span class="rule-table-ru">ночь</span></td><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">ٱسْمٌ مَجْرُورٌ بِفِي</span><span class="rule-table-ru">имя в родительном падеже после предлога «в»</span></td></tr></tbody></table></div></div></div>', 1, 'rule', 'Маф‘уль фихи — имя в винительном падеже с подразумеваемым предлогом «в», обозначающее время или место действия; оно называется обстоятельством.', 'الْمَفْعُولُ فِيهِ ٱسْمٌ مَنْصُوبٌ بِتَقْدِيرِ فِي، يُذْكَرُ لِبَيَانِ زَمَنِ وُقُوعِ الْفِعْلِ أَوْ مَكَانِهِ، وَيُسَمَّى ظَرْفًا. وَالظَّرْفُ نَوْعَانِ: ظَرْفُ زَمَانٍ وَظَرْفُ مَكَانٍ.'),
    ('Мединский курс (Том 3)', '12', 'الْمُعْرَبُ وَالْمَبْنِيُّ مِنَ الظُّرُوفِ (изменяемые и неизменяемые обстоятельственные имена)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar" dir="rtl" lang="ar">الظُّرُوفُ كُلُّهَا <span class="ar-tone-structure">مُعْرَبَةٌ</span> إِلَّا أَلْفَاظًا مَعْدُودَةً تَكُونُ <span class="ar-tone-structure">مَبْنِيَّةً</span>.</span><p class="rule-study-text">Все обстоятельственные имена изменяемы, кроме ограниченного числа неизменяемых слов.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Неизменяемые обстоятельства времени</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">اللَّفْظُ</span><span class="rule-table-ru">слово</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَعْنَاهُ بِالرُّوسِيَّةِ</span><span class="rule-table-ru">русское значение</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">مَتَى</span><span class="rule-table-ru">когда</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">أَمْسِ</span><span class="rule-table-ru">вчера</span></td></tr><tr><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">قَطُّ</span><span class="rule-table-ru">когда-либо; всегда в отрицательном контексте</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">الْآنَ</span><span class="rule-table-ru">сейчас</span></td></tr><tr><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">إِذَا</span><span class="rule-table-ru">когда; если</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">إِذْ</span><span class="rule-table-ru">когда; поскольку</span></td></tr><tr><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">أَيَّانَ</span><span class="rule-table-ru">когда</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">بَيْنَمَا</span><span class="rule-table-ru">в то время как</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Неизменяемые обстоятельства места</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">اللَّفْظُ</span><span class="rule-table-ru">слово</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَعْنَاهُ بِالرُّوسِيَّةِ</span><span class="rule-table-ru">русское значение</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">أَيْنَ</span><span class="rule-table-ru">где</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">حَيْثُ</span><span class="rule-table-ru">где; там, где</span></td></tr><tr><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">هُنَا</span><span class="rule-table-ru">здесь</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">هُنَاكَ</span><span class="rule-table-ru">там</span></td></tr><tr><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">ثَمَّ</span><span class="rule-table-ru">там</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">ظَرْفُ مَكَانٍ</span><span class="rule-table-ru">обстоятельство места</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Точная форма публичного текста</span><p class="rule-study-text">В дословном источнике сохранено написание <span class="ar-inline" dir="rtl" lang="ar">إِذَاْ، بَيْنَمَاْ</span>. В учебной формулировке формы показаны без ошибочного сукуна на конечном алифе: <span class="ar-inline ar-tone-nasb" dir="rtl" lang="ar">إِذَا، بَيْنَمَا</span>.</p></div></div>', 2, 'rule', 'По общему правилу обстоятельственные имена изменяемы; шарх отдельно перечисляет ограниченный набор неизменяемых обстоятельств времени и места.', 'الظُّرُوفُ كُلُّهَا مُعْرَبَةٌ إِلَّا أَلْفَاظًا مَعْدُودَةً؛ فَمِنْ ظُرُوفِ الزَّمَانِ الْمَبْنِيَّةِ: مَتَى، وَأَمْسِ، وَقَطُّ، وَالْآنَ، وَإِذَا، وَإِذْ، وَأَيَّانَ، وَبَيْنَمَا. وَمِنْ ظُرُوفِ الْمَكَانِ الْمَبْنِيَّةِ: أَيْنَ، وَحَيْثُ، وَهُنَا، وَهُنَاكَ، وَثَمَّ.'),
    ('Мединский курс (Том 3)', '12', 'النَّائِبُ عَنِ الظَّرْفِ (заместитель обстоятельственного имени)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar" dir="rtl" lang="ar">يَنُوبُ عَنِ <span class="ar-tone-nasb">الظَّرْفِ</span> أَرْبَعَةُ أُمُورٍ: مَا أُضِيفَ إِلَى الظَّرْفِ وَدَلَّ عَلَى كُلِّيَّتِهِ أَوْ جُزْئِيَّتِهِ، وَصِفَتُهُ، وَٱسْمُ الْإِشَارَةِ، وَعَدَدُهُ.</span><p class="rule-study-text">Шарх называет четыре вида слов, которые могут занимать синтаксическую позицию обстоятельства.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Четыре вида заместителя</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">النَّوْعُ</span><span class="rule-table-ru">вид</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْأَمْثِلَةُ</span><span class="rule-table-ru">все примеры и перевод</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">الْمُضَافُ إِلَى الظَّرْفِ الدَّالُّ عَلَى الْكُلِّيَّةِ أَوِ الْجُزْئِيَّةِ</span><span class="rule-table-ru">слово в идафе с обстоятельством, обозначающее целое или часть</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">سَافَرْنَا كُلَّ النَّهَارِ. سِرْتُ بَعْضَ النَّهَارِ. مَشَيْتُ نِصْفَ كِيلُومِتْرٍ.</span><span class="rule-table-ru">Мы путешествовали весь день. Я шёл часть дня. Я прошёл половину километра.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">صِفَةُ الظَّرْفِ</span><span class="rule-table-ru">характеристика времени или места</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">جَلَسْتُ طَوِيلًا مِنَ الْوَقْتِ، أَيْ: جَلَسْتُ وَقْتًا طَوِيلًا. نِمْتُ قَلِيلًا، أَيْ: نِمْتُ وَقْتًا قَلِيلًا.</span><span class="rule-table-ru">Я просидел долгое время, то есть просидел длительное время. Я спал недолго, то есть спал мало времени.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">ٱسْمُ الْإِشَارَةِ</span><span class="rule-table-ru">указательное имя</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">جِئْتُ هَذَا الْأُسْبُوعَ. سَافَرْتُ ذَلِكَ الْيَوْمَ. ذَهَبْتُ تِلْكَ النَّاحِيَةَ.</span><span class="rule-table-ru">Я пришёл на этой неделе. Я отправился в поездку в тот день. Я пошёл в ту сторону.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">عَدَدُ الظَّرْفِ</span><span class="rule-table-ru">число единиц времени или расстояния</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">سَافَرْتُ ثَلَاثِينَ يَوْمًا. سِرْتُ ثَلَاثَةَ أَمْيَالٍ.</span><span class="rule-table-ru">Я путешествовал тридцать дней. Я прошёл три мили.</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Полный إِعْرَاب: обычные обстоятельства</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример и перевод</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْكَلِمَةُ</span><span class="rule-table-ru">разбираемое слово</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">إِعْرَابُهَا</span><span class="rule-table-ru">полный разбор и перевод</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">سَافَرْتُ لَيْلًا.</span><span class="rule-table-ru">Я путешествовал ночью.</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">لَيْلًا</span><span class="rule-table-ru">ночью</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">ظَرْفُ زَمَانٍ مَنْصُوبٌ، وَعَلَامَةُ نَصْبِهِ الْفَتْحَةُ الظَّاهِرَةُ.</span><span class="rule-table-ru">обстоятельство времени в винительном падеже; признак винительного падежа — явно выраженная фатха</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">نِمْتُ تَحْتَ الشَّجَرَةِ.</span><span class="rule-table-ru">Я спал под деревом.</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">تَحْتَ</span><span class="rule-table-ru">под</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">ظَرْفُ مَكَانٍ مَنْصُوبٌ، وَعَلَامَةُ نَصْبِهِ الْفَتْحَةُ الظَّاهِرَةُ.</span><span class="rule-table-ru">обстоятельство места в винительном падеже; признак винительного падежа — явно выраженная фатха</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Полный إِعْرَاب: неизменяемые обстоятельства</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример и перевод</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْكَلِمَةُ</span><span class="rule-table-ru">разбираемое слово</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">إِعْرَابُهَا</span><span class="rule-table-ru">полный разбор и перевод</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَتَى خَرَجْتَ؟</span><span class="rule-table-ru">Когда ты вышел?</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">مَتَى</span><span class="rule-table-ru">когда</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">ٱسْمُ ٱسْتِفْهَامٍ مَبْنِيٌّ عَلَى السُّكُونِ فِي مَحَلِّ نَصْبٍ ظَرْفُ زَمَانٍ.</span><span class="rule-table-ru">вопросительное имя, построенное на сукуне, в синтаксическом месте винительного падежа как обстоятельство времени</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">أَيْنَ تَدْرُسُ؟</span><span class="rule-table-ru">Где ты учишься?</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">أَيْنَ</span><span class="rule-table-ru">где</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">ٱسْمُ ٱسْتِفْهَامٍ مَبْنِيٌّ عَلَى الْفَتْحِ فِي مَحَلِّ نَصْبٍ ظَرْفُ مَكَانٍ.</span><span class="rule-table-ru">вопросительное имя, построенное на фатхе, в синтаксическом месте винительного падежа как обстоятельство места</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Полный إِعْرَاب: заместители обстоятельства</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример и перевод</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْكَلِمَةُ</span><span class="rule-table-ru">разбираемое слово</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">إِعْرَابُهَا</span><span class="rule-table-ru">полный разбор и перевод</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">ذَهَبْتُ تِلْكَ النَّاحِيَةَ.</span><span class="rule-table-ru">Я пошёл в ту сторону.</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">تِلْكَ</span><span class="rule-table-ru">ту</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">ٱسْمُ إِشَارَةٍ مَبْنِيٌّ عَلَى الْفَتْحِ فِي مَحَلِّ نَصْبٍ مَفْعُولٌ فِيهِ نَائِبٌ عَنْ ظَرْفِ الْمَكَانِ.</span><span class="rule-table-ru">указательное имя, построенное на фатхе, в синтаксическом месте винительного падежа как маф‘уль фихи, заменяющий обстоятельство места</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">سَافَرْنَا كُلَّ النَّهَارِ.</span><span class="rule-table-ru">Мы путешествовали весь день.</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">كُلَّ</span><span class="rule-table-ru">весь</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">مَفْعُولٌ فِيهِ نَائِبٌ عَنْ ظَرْفِ الزَّمَانِ مَنْصُوبٌ، وَعَلَامَةُ نَصْبِهِ الْفَتْحَةُ الظَّاهِرَةُ.</span><span class="rule-table-ru">маф‘уль фихи, заменяющий обстоятельство времени, в винительном падеже; признак — явно выраженная фатха</span></td></tr></tbody></table></div></div></div>', 3, 'rule', 'Роль обстоятельства могут занимать слово, присоединённое к обозначению времени или места, его характеристика, указательное имя либо число.', 'يَنُوبُ عَنِ الظَّرْفِ أَرْبَعَةُ أُمُورٍ: الْمُضَافُ إِلَى الظَّرْفِ مِمَّا دَلَّ عَلَى كُلِّيَّةِ الزَّمَانِ أَوِ الْمَكَانِ أَوْ جُزْئِيَّتِهِمَا، وَصِفَةُ الظَّرْفِ، وَٱسْمُ الْإِشَارَةِ، وَعَدَدُ الظَّرْفِ.'),
    ('Мединский курс (Том 3)', '12', 'قَبْلُ وَبَعْدُ (слова «до» и «после»)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar" dir="rtl" lang="ar"><span class="ar-tone-nasb">قَبْلُ وَبَعْدُ</span> مُعْرَبَتَانِ، وَتَكُونَانِ مَبْنِيَّتَيْنِ عَلَى الضَّمِّ فِي حَالَةٍ وَاحِدَةٍ: إِذَا حُذِفَ الْمُضَافُ إِلَيْهِ لَفْظًا لَا مَعْنًى.</span><p class="rule-study-text">Обычно эти два слова изменяются. Они становятся неизменяемыми на дамме только тогда, когда зависимое слово не произнесено, но сохраняется в подразумеваемом смысле.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Когда зависимое слово названо</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример и перевод</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">صِيغَةُ قَبْلٍ وَبَعْدٍ</span><span class="rule-table-ru">форма слов «до» и «после»</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْحُكْمُ</span><span class="rule-table-ru">грамматическое положение</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">جِئْتُ قَبْلَ الْعِيدِ وَبَعْدَهُ.</span><span class="rule-table-ru">Я пришёл до праздника и после него.</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">قَبْلَ، بَعْدَ</span><span class="rule-table-ru">до; после</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">مُعْرَبَتَانِ مَنْصُوبَتَانِ</span><span class="rule-table-ru">оба слова изменяемы и стоят в винительном падеже</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">جِئْتُ مِنْ قَبْلِ الْعِيدِ وَمِنْ بَعْدِهِ.</span><span class="rule-table-ru">Я пришёл до праздника и после него.</span></td><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">قَبْلِ، بَعْدِ</span><span class="rule-table-ru">до; после</span></td><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">مُعْرَبَتَانِ مَجْرُورَتَانِ بِمِنْ</span><span class="rule-table-ru">оба слова изменяемы и стоят в родительном падеже после предлога</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Коранический пример</span><div class="rule-example-card"><span class="rule-example-ar rule-quran-ar ar-tone-structure" dir="rtl" lang="ar">﴿ لِلَّهِ الْأَمْرُ مِنْ قَبْلُ وَمِنْ بَعْدُ ﴾</span><span class="rule-example-ru">«Аллаху принадлежит власть до и после».</span></div></div><div class="rule-study-card"><span class="rule-card-kicker">Что опущено в аяте</span><span class="rule-main-ar ar-tone-structure" dir="rtl" lang="ar">حُذِفَ الْمُضَافُ إِلَيْهِ، وَهُوَ <span class="ar-tone-jarr">الْغَلَبَةُ</span>، لَفْظًا وَلَكِنَّهُ مَنْوِيٌّ فِي الْمَعْنَى.</span><p class="rule-study-text">Зависимое слово «победа» не произнесено, но подразумевается по смыслу.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Аналогичный пример шарха</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример и перевод</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَحْذُوفُ لَفْظًا</span><span class="rule-table-ru">что опущено в речи</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْحُكْمُ</span><span class="rule-table-ru">грамматическое положение</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">جِئْتُ قَبْلُ وَبَعْدُ.</span><span class="rule-table-ru">Я пришёл до и после.</span></td><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">الْعِيدُ</span><span class="rule-table-ru">праздник</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">قَبْلُ وَبَعْدُ مَبْنِيَّتَانِ عَلَى الضَّمِّ</span><span class="rule-table-ru">оба слова построены на дамме</span></td></tr></tbody></table></div></div></div>', 4, 'rule', 'Слова «до» и «после» изменяемы при названном зависимом слове и строятся на дамме, когда зависимое слово опущено в речи, но подразумевается по смыслу.', 'قَبْلُ وَبَعْدُ مُعْرَبَتَانِ إِذَا ذُكِرَ الْمُضَافُ إِلَيْهِ، وَتَكُونَانِ مَبْنِيَّتَيْنِ عَلَى الضَّمِّ إِذَا حُذِفَ الْمُضَافُ إِلَيْهِ لَفْظًا وَنُوِيَ مَعْنًى.'),
    ('Мединский курс (Том 3)', '12', 'لَوْ (условная частица «если бы»)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar" dir="rtl" lang="ar"><span class="ar-tone-particle">لَوْ</span> حَرْفُ امْتِنَاعٍ لِامْتِنَاعٍ، وَهِيَ حَرْفُ شَرْطٍ غَيْرُ جَازِمٍ يَحْتَاجُ إِلَى شَرْطٍ وَجَوَابٍ.</span><p class="rule-study-text">Это неуправляющая условная частица: она требует условие и ответ и выражает неосуществление ответа вследствие неосуществления условия.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Три значения, названные автором</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَعْنَى</span><span class="rule-table-ru">значение</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">شَرْحُهُ</span><span class="rule-table-ru">точное объяснение</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">الشَّرْطِيَّةُ</span><span class="rule-table-ru">условность</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">تَحْتَاجُ إِلَى شَرْطٍ وَجَوَابٍ، وَهِيَ حَرْفُ شَرْطٍ غَيْرُ جَازِمٍ.</span><span class="rule-table-ru">требует условие и ответ; является неуправляющей условной частицей</span></td></tr><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">تَقْيِيدُ الشَّرْطِيَّةِ بِالزَّمَنِ الْمَاضِي</span><span class="rule-table-ru">отнесение условности к прошлому</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">شَرْطُهَا وَجَوَابُهَا لَمْ يَتَحَقَّقَا فِي الزَّمَنِ الْمَاضِي.</span><span class="rule-table-ru">её условие и ответ не осуществились в прошлом</span></td></tr><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">الِامْتِنَاعُ</span><span class="rule-table-ru">неосуществление</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">امْتِنَاعُ الْجَوَابِ لِامْتِنَاعِ الشَّرْطِ.</span><span class="rule-table-ru">ответ не осуществился из-за неосуществления условия</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Смысл основной конструкции</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْجُمْلَةُ</span><span class="rule-table-ru">предложение и перевод</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَعْنَاهَا</span><span class="rule-table-ru">подразумеваемый смысл</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">لَوِ ٱجْتَهَدْتَ لَنَجَحْتَ.</span><span class="rule-table-ru">Если бы ты усердствовал, то преуспел бы.</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">لَمْ تَجْتَهِدْ فَلَمْ تَنْجَحْ.</span><span class="rule-table-ru">Ты не усердствовал и поэтому не преуспел.</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Ответ частицы لَوْ</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">نَوْعُ الْجَوَابِ</span><span class="rule-table-ru">вид ответа</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">حُكْمُ اللَّامِ</span><span class="rule-table-ru">употребление ляма</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример и перевод</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">الْجَوَابُ الْمُثْبَتُ</span><span class="rule-table-ru">утвердительный ответ</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">يَقْتَرِنُ بِلَامِ الْجَوَابِ كَثِيرًا</span><span class="rule-table-ru">часто соединяется с лямом ответа</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">لَوْ نَشَاءُ لَجَعَلْنَاهُ حُطَامًا.</span><span class="rule-table-ru">Если бы Мы пожелали, то превратили бы его в сухие обломки.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">الْجَوَابُ الْمُثْبَتُ</span><span class="rule-table-ru">утвердительный ответ</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">قَدْ لَا يَقْتَرِنُ بِاللَّامِ، وَهُوَ قَلِيلٌ</span><span class="rule-table-ru">иногда не соединяется с лямом; это редко</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">لَوْ نَشَاءُ جَعَلْنَاهُ أُجَاجًا.</span><span class="rule-table-ru">Если бы Мы пожелали, то сделали бы её горько-солёной.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">الْجَوَابُ الْمَنْفِيُّ</span><span class="rule-table-ru">отрицательный ответ</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">لَا يَقْتَرِنُ بِاللَّامِ</span><span class="rule-table-ru">обычно не соединяется с лямом</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">لَوْ حَضَرْتَ الِامْتِحَانَ مَا رَسَبْتَ.</span><span class="rule-table-ru">Если бы ты присутствовал на экзамене, то не провалился бы.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">الْجَوَابُ الْمَنْفِيُّ</span><span class="rule-table-ru">отрицательный ответ</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">قَدْ يَقْتَرِنُ بِاللَّامِ، وَهُوَ قَلِيلٌ</span><span class="rule-table-ru">иногда соединяется с лямом; это редко</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">لَوْ حَضَرْتَ الِامْتِحَانَ لَمَا رَسَبْتَ.</span><span class="rule-table-ru">Если бы ты присутствовал на экзамене, то не провалился бы.</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Коранический пример</span><div class="rule-example-card"><span class="rule-example-ar rule-quran-ar ar-tone-particle" dir="rtl" lang="ar">﴿ لَوْ نَشَاءُ لَجَعَلْنَاهُ حُطَامًا ﴾</span><span class="rule-example-ru">«Если бы Мы пожелали, то превратили бы его в сухие обломки».</span></div></div><div class="rule-study-card"><span class="rule-card-kicker">Коранический пример</span><div class="rule-example-card"><span class="rule-example-ar rule-quran-ar ar-tone-particle" dir="rtl" lang="ar">﴿ لَوْ نَشَاءُ جَعَلْنَاهُ أُجَاجًا ﴾</span><span class="rule-example-ru">«Если бы Мы пожелали, то сделали бы её горько-солёной».</span></div></div><div class="rule-study-card"><span class="rule-card-kicker">Полный إِعْرَاب частиц</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">اللَّفْظُ</span><span class="rule-table-ru">элемент</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">إِعْرَابُهُ</span><span class="rule-table-ru">арабский разбор</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">التَّرْجَمَةُ</span><span class="rule-table-ru">полный перевод разбора</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">لَوْ</span><span class="rule-table-ru">если бы</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">حَرْفُ امْتِنَاعٍ لِامْتِنَاعٍ مَبْنِيٌّ عَلَى السُّكُونِ لَا مَحَلَّ لَهُ مِنَ الْإِعْرَابِ.</span><span class="rule-table-ru">частица неосуществления вследствие неосуществления, построенная на сукуне и не имеющая синтаксического места</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">لَا مَحَلَّ لَهُ مِنَ الْإِعْرَابِ</span><span class="rule-table-ru">не является членом предложения</span></td></tr><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">لَامُ الْجَوَابِ</span><span class="rule-table-ru">лям ответа</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">حَرْفُ جَوَابٍ وَرَبْطٍ مَبْنِيٌّ عَلَى الْفَتْحِ لَا مَحَلَّ لَهُ مِنَ الْإِعْرَابِ.</span><span class="rule-table-ru">частица ответа и связи, построенная на фатхе и не имеющая синтаксического места</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">لَا مَحَلَّ لَهَا مِنَ الْإِعْرَابِ</span><span class="rule-table-ru">не является членом предложения</span></td></tr></tbody></table></div></div></div>', 5, 'rule', 'Условная частица «если бы» относится к прошлому: условие не осуществилось, поэтому не осуществился и ответ; она не ставит глагол в усечённую форму.', 'لَوْ حَرْفُ امْتِنَاعٍ لِامْتِنَاعٍ، وَهِيَ حَرْفُ شَرْطٍ غَيْرُ جَازِمٍ يَحْتَاجُ إِلَى شَرْطٍ وَجَوَابٍ، وَتُقَيِّدُ الشَّرْطِيَّةَ بِالزَّمَنِ الْمَاضِي، وَيَمْتَنِعُ الْجَوَابُ لِامْتِنَاعِ الشَّرْطِ.');

  insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
  select id, 'Sharkh_Medinskiy_3.pdf', 'الْمَفْعُولُ فِيهِ
المفعولُ فيه : اسمٌ منصوبٌ بتقديرِ ( في ) يُذْكَرُ لِبَيَانِ زَمَنِ وُقُوعِ الفعلِ أو مَكَانِهِ .
ويُسَمَّى : ظَرْفاً .
الظَّرْفُ نوعان : ظرفُ زَمَانٍ               وظرفُ مَكَانٍ .
الأمثلة :
( أ ) ظرفُ الزَّمَانِ ، نحو : سافرت لَيلاً ( أي : في اللَّيلِ ) ونحو : خرجت مساءً .
جئت قبلَ ساعةٍ . سأسافر صباحاً أو غداً إن شاء الله . نمت بعدَ نومِك .
قال تعالى : ﴿ وَجَاءُوا أَبَاهُمْ عِشَاءً يَبْكُونَ ﴾ .
(ب) ظرفُ الْمَكَانِ ، نحو : جلست هُنا ( أي : في هذا المكان ) ونحو : مَشَيْتُ يَمِينَ الطَّريق ( أي : في يمين الطريق ) ونحو :  مَشَيْتُ مِيلاً . جلست عندَ المديرِ . نمت تحتَ الشجرةِ ، قال تعالى : ﴿ وَبَنَيْنَا فَوْقَكُمْ سَبْعًا شِدَادًا ﴾ .
* إذا لَمْ تُقَدَّر ( فِي ) لا يُعْرَبُ ظرفاً ، وكذلك إذا ذُكرت ( فِي ) لا يُعربُ ظرفاً ، نحو :
هذا يومُ العيدِ        خبر مرفوع        سافرت في الليلِ       اسم مجرور', 48, 49, 1
  from public.rules where course_name = 'Мединский курс (Том 3)' and lesson_number = '12' and sort_order = 1;

  insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
  select id, 'Sharkh_Medinskiy_3.pdf', 'المعربُ والمبنيُّ مِن الظُّرُوفِ :
الظُّروفُ كلُّها مُعْرَبَةٌ ( كما في الأمثلة السَّابقةِ ) إلا ألفاظاً مَعْدُودةً ، منها :
1- ظروفُ الزَّمانِ المبنيَّةُ : مَتَى ، أَمْسِ ، قَطُّ ، الآنَ ، إِذَاْ ، إِذْ ، أَيَّانَ ، بَيْنَمَاْ .
2- ظروفُ المكانِ المبنيَّةُ : أينَ ، حَيْثُ ، هُنَا ، هُنَاكَ ، ثَمَّ .', 49, 49, 1
  from public.rules where course_name = 'Мединский курс (Том 3)' and lesson_number = '12' and sort_order = 2;

  insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
  select id, 'Sharkh_Medinskiy_3.pdf', 'النَّائِبُ عن الظَّرفِ : يَنُوبُ عن الظَّرف أحد الأمورِ الآتية :
1- المضافُ إلى الظَّرفِ مِمَّا دَلَّ على كُلِّيَّة الزَّمانِ ، أو المكانِ ، أو جُزْئِيَّتِهِمَا ، نحو :
سافرنا كلَّ النَّهارِ . سِرْتُ بعضَ النَّهارِ . مَشَيْتُ نِصْفَ كيلومترٍ .
2- صِفَتُهُ ، نحو : جلستُ طويلاً من الوَقْت ، أي : جلست وقتاً طويلاً .
ونحو : نمت قليلاً ، أي : نمت وقتاً قليلاً .
3- اسمُ الإشارةِ ، نحو : جئت هذا الأسبوعَ . سافرت ذلك اليومَ . ذهبتُ تلكَ النَّاحِيَةَ.
4- عَدَدُهُ ، نحو : سافرت ثلاثين يوماً .   سِرْتُ ثلاثةَ أَمْيَالٍ .
الإعراب :
* سافرت ليلاً .
ليلاً : ظرف زمان منصوب وعلامة نصبه الفتحة الظاهرة .
* نمتُ تحتَ الشجرةِ .
تحتَ : ظرف مكان منصوب وعلامة نصبه الفتحة الظاهرة .
* مَتى خرجتَ ؟
متى : اسم استفهام مبني على السكون في محل نصب ظرف زمان .
* أين تدرسُ ؟
أينَ : اسم اسَتفهام مبني على الفتح في محل نصب ظرف مكان .
* ذهبتُ تلكَ النَّاحِيَةَ .
تلكَ : اسم إشارة مبني على الفتح في محل نصب مفعول فيه نائب عن ظرف المكان .
* سافرنا كلَّ النَّهارِ .
كلَّ : مفعول فيه نائب عن ظرف الزمان منصوب وعلامة نصبه الفتحة الظاهرة .', 49, 50, 1
  from public.rules where course_name = 'Мединский курс (Том 3)' and lesson_number = '12' and sort_order = 3;

  insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
  select id, 'Sharkh_Medinskiy_3.pdf', 'قَبْلُ ، وبَعْدُ : مُعْرَبَتَانِ ، نحو : جئتُ قبلَ العيدِ وبعدَه . جئت مِن قبلِ العيدِ ومن بعدِه .
وتكونان مَبْنِيَّتان على الضَّمَّ في حالة واحدة فقط ، هي :
إذا حُذِف الْمُضَاف إليه لفظاً لا معنىً ، كما في قوله تعالى : ﴿ لِلَّهِ الْأَمْرُ مِنْ قَبْلُ وَمِنْ بَعْدُ ﴾ فَحُذِف المضاف إليه ، وهو ( الْغَلَبَة ) لفظاً ولكنَّه مَنْوِيٌّ في المعنى .
ومثله قولك: جئت قبلُ وبعدُ ، بحذف المضاف إليه ( العيد ) لفظاً ، وهو منوي في المعنى.', 51, 51, 1
  from public.rules where course_name = 'Мединский курс (Том 3)' and lesson_number = '12' and sort_order = 4;

  insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
  select id, 'Sharkh_Medinskiy_3.pdf', 'لَوْ
لَوْ : حرفُ امْتِنَاعٍ لاِمْتِنَاعٍ . وتُفِيدُ ثلاثةَ أُمُورٍ ، هي :
1- الشَّرْطِيَّةُ ، فهي تحتاج إلى شَرْطٍ وجَوَابٍ . وهي حرفُ شَرْطٍ غيرُ جَازِم .
2- تَقْيِيدُ الشَّرْطيَّة بالزَّمَنِ الماضي ؛ لذلك شَرْطُها ، وجوابُها لم يَتَحَقَّقَا في الزمن الماضي.
3- الامْتِنَاعُ ، أي : امتناع الجواب لامتناع الشَّرط .
فمعنى قولك : لو اجتهدْتَ لنجحتَ ، أي: لم تجتهد فلم تنجحْ ، وذلك في الزمن الماضي.
* جوابُها الْمُثْبَتُ يقترنُ باللاَّم كثيراً ،كما في قوله تعالى: ﴿ لَوْ نَشَاءُ لَجَعَلْنَاهُ حُطَامًا ﴾ .
وقد لا يقترن باللاَّم ، وهو قليل ، قال تعالى : ﴿ لَوْ نَشَاءُ جَعَلْنَاهُ أُجَاجًا ﴾ .
وجوابُها الْمَنْفِيُّ لا يقترن باللام ، نحو : لو حضرتَ الامتحانَ ما رَسَبْتَ .
وقد يقترن باللاَّم ، وهو قليل ، نحو : لو حضرتَ الامتحانَ لَمَا رسبتَ .
* لو : حرف امتناع لامتناع مبني على السكون لا محلّ له من الإعراب .
* لام الجواب : حرف جواب ورَبْط مبني على الفتح لا محلّ له من الإعراب .', 51, 52, 1
  from public.rules where course_name = 'Мединский курс (Том 3)' and lesson_number = '12' and sort_order = 5;

  select count(*) into new_rule_count from public.rules where course_name = 'Мединский курс (Том 3)' and lesson_number = '12';
  select count(*) into source_count from public.rule_sources rs join public.rules r on r.id = rs.rule_id where r.course_name = 'Мединский курс (Том 3)' and r.lesson_number = '12';
  if new_rule_count <> 5 or source_count <> 5 then raise exception 'Book 3 lesson 12 verification failed: rules %, sources %', new_rule_count, source_count; end if;
end
